<script setup lang="ts">
definePageMeta({ layout: 'dashboard', middleware: 'auth', roles: ['marketing', 'editor'] })
useHead({ title: 'Kategori Konten | Marketing Hub', meta: [{ name: 'robots', content: 'noindex' }] })
const { public: config } = useRuntimeConfig(); const categories = ref<{ id: string, name: string, slug: string, description: string, position: number }[]>([]); const form = reactive({ name: '', slug: '', description: '' }); const pending = ref(true); const saving = ref(false); const error = ref('')
async function load() { pending.value = true; try { categories.value = await useApiFetch('/marketing/categories', { baseURL: config.apiBase, credentials: 'include' }) } catch { error.value = 'Kategori belum berhasil dimuat.' } finally { pending.value = false } }
async function create() { if (!form.name.trim()) return; saving.value = true; error.value = ''; try { await useApiFetch('/marketing/categories', { baseURL: config.apiBase, method: 'POST', credentials: 'include', body: form }); form.name = ''; form.slug = ''; form.description = ''; await load() } catch { error.value = 'Kategori belum berhasil disimpan.' } finally { saving.value = false } }
onMounted(load)
</script>
<template><div class="grid gap-6"><AppPageHeader title="Kategori Konten" description="Susun taksonomi artikel edukasi Zenko." /><AppInlineMessage v-if="error" type="error">{{ error }}</AppInlineMessage><div class="grid gap-6 xl:grid-cols-[minmax(0,1fr)_20rem]"><AppPanel header="Daftar kategori" :collapsible="false"><DashboardSkeleton v-if="pending" variant="rows" :count="5" /><AppEmptyState v-else-if="!categories.length" title="Belum ada kategori" description="Tambahkan kategori pertama untuk mengelompokkan artikel." /><ul v-else class="divide-y divide-hairline"><li v-for="category in categories" :key="category.id" class="py-4 first:pt-0"><p class="font-semibold text-ink">{{ category.name }}</p><p class="mt-1 text-xs text-muted">/artikel/kategori/{{ category.slug }}<span v-if="category.description"> · {{ category.description }}</span></p></li></ul></AppPanel><AppPanel header="Kategori baru" :collapsible="false"><form class="grid gap-4" @submit.prevent="create"><AppTextField id="category-name" v-model="form.name" label="Nama" placeholder="SKD CPNS" /><AppTextField id="category-slug" v-model="form.slug" label="Slug opsional" placeholder="skd-cpns" /><AppTextField id="category-description" v-model="form.description" label="Deskripsi" /><AppButton type="submit" :loading="saving">Tambah kategori</AppButton></form></AppPanel></div></div></template>
